#!/usr/bin/env bash
# MSA + template search for the ASSEMBLY-derived protein-protein inputs.
#
# WHY A SECOND ARM. ops/pp_prep.sh built inputs from the RCSB ASYMMETRIC UNIT, which is correct for
# heterotypic complexes (an ab-ag ASU holds every distinct chain) but wrong for homodimers: the ASU
# often holds ONE copy and the second is generated by crystal symmetry. Those targets were predicted
# as monomers, so the benchmark interface (A | A-2) does not exist in the output and no DockQ can be
# computed -- 37 complexes were unscoreable for this reason.
#
# Neither source is universally right: 7st5's ASU gives count=2 while its assembly1 gives count=1.
# Under-prediction is fatal (no interface), over-prediction is not (OST matches the best copies), so
# this arm is restricted to the 43 targets where the ASSEMBLY yields MORE copies than the ASU.
# 8tlf and 8jzt are excluded: their ASU already supplies >=2 copies, so re-running would only regress.
set -o pipefail
REPO=/home/ebrahim/tts_abag/confident_decoy_experiments
PP=$REPO/artifacts/pp
CLI=/home/ebrahim/Protenix/.venv/bin/protenix
LIST=$1
cd /home/ebrahim/Protenix || exit 1
say(){ echo "[$(date '+%F %T')] $*" | tee -a $REPO/ops/pp_prep_asm.log; }
say "MSA+template for $(wc -l < "$LIST") assembly-derived inputs"
n=0
while read -r p; do
  [ -z "$p" ] && continue
  [ -s "$PP/jsons_asm/${p}-final-updated.json" ] && { say "  $p already done"; continue; }
  $CLI mt --input "$PP/jsons_asm/${p}.json" --out_dir "$PP/prep_asm/${p}" >> $REPO/ops/pp_prep_asm.log 2>&1 \
    || say "  FAIL $p"
  n=$((n+1)); say "  [$n] $p -> $([ -s "$PP/jsons_asm/${p}-final-updated.json" ] && echo ok || echo MISSING)"
done < "$LIST"
say "DONE: $(ls $PP/jsons_asm/*-final-updated.json 2>/dev/null | wc -l) final inputs ready"
